package pe.bibliored;
import pe.bibliored.dao.*;import pe.bibliored.service.*;import org.junit.jupiter.api.*;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.boot.test.context.SpringBootTest;import org.springframework.boot.test.autoconfigure.web.servlet.AutoConfigureMockMvc;import org.springframework.test.web.servlet.MockMvc;import org.springframework.transaction.annotation.Transactional;import java.time.LocalDate;import static org.junit.jupiter.api.Assertions.*;import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;import static org.springframework.security.test.web.servlet.request.SecurityMockMvcRequestPostProcessors.*;
@SpringBootTest(properties={"spring.datasource.url=jdbc:h2:mem:test;DB_CLOSE_DELAY=-1","spring.jpa.hibernate.ddl-auto=create-drop"}) @AutoConfigureMockMvc @Transactional class FlujoIntegrationTest {
@Autowired PrestamoService servicio;@Autowired EjemplarDao ejemplares;@Autowired PrestamoDao prestamos;@Autowired MultaDao multas;@Autowired MockMvc mvc;
@Test void flujoCompleto(){var p=servicio.solicitar(3L,1L,LocalDate.now());assertEquals("RESERVADO",ejemplares.findById(1L).orElseThrow().estado);servicio.entregar(p.id);assertEquals(LocalDate.now().plusDays(14),p.fechaLimite);servicio.devolver(p.id,"Correcto");assertEquals("DISPONIBLE",ejemplares.findById(1L).orElseThrow().estado);assertEquals("DEVUELTO",p.estado);}
@Test void rechazaDobleReserva(){servicio.solicitar(3L,1L,LocalDate.now());assertThrows(IllegalArgumentException.class,()->servicio.solicitar(3L,1L,LocalDate.now()));}
@Test void rechazaFechaPasada(){assertThrows(IllegalArgumentException.class,()->servicio.solicitar(3L,1L,LocalDate.now().minusDays(1)));}
@Test void impideDobleDevolucion(){var p=servicio.solicitar(3L,1L,LocalDate.now());servicio.entregar(p.id);servicio.devolver(p.id,"");assertThrows(IllegalArgumentException.class,()->servicio.devolver(p.id,""));}
@Test void generaMultaYBloqueaNuevaSolicitud(){var p=servicio.solicitar(3L,1L,LocalDate.now());servicio.entregar(p.id);p.fechaLimite=LocalDate.now().minusDays(3);prestamos.save(p);servicio.devolver(p.id,"");assertEquals(0,new java.math.BigDecimal("3").compareTo(multas.findAll().get(0).monto));assertThrows(IllegalArgumentException.class,()->servicio.solicitar(3L,2L,LocalDate.now()));}
@Test void rechazaSolicitudConPrestamoVencido(){var p=servicio.solicitar(3L,1L,LocalDate.now());servicio.entregar(p.id);p.fechaLimite=LocalDate.now().minusDays(1);prestamos.save(p);assertThrows(IllegalArgumentException.class,()->servicio.solicitar(3L,2L,LocalDate.now()));}
@Test void requiereSesion()throws Exception{mvc.perform(get("/api/catalogo")).andExpect(status().isUnauthorized());}
@Test void lectorNoAdmin()throws Exception{mvc.perform(get("/api/admin/usuarios").with(user("lector@bibliored.local").roles("USUARIO"))).andExpect(status().isForbidden());}
@Test void exigeCsrf()throws Exception{mvc.perform(post("/api/prestamos").with(user("lector@bibliored.local").roles("USUARIO")).contentType("application/json").content("{\"ejemplarId\":1,\"fechaRecojo\":\"2026-10-27\"}")).andExpect(status().isForbidden());}
@Test void ocultaHash()throws Exception{mvc.perform(get("/api/yo").with(user("lector@bibliored.local").roles("USUARIO"))).andExpect(status().isOk()).andExpect(jsonPath("$.passwordHash").doesNotExist());}
@Test void catalogoBuscaPorCodigo()throws Exception{mvc.perform(get("/api/catalogo?q=LIB-001").with(user("lector@bibliored.local").roles("USUARIO"))).andExpect(status().isOk()).andExpect(jsonPath("$.length()").value(1));}
}
